import sqlite3
import sys

sys.path.insert(0, ".")
from supply_guard.catalog import Catalog
from supply_guard.cli import render_summary

conn = sqlite3.connect(":memory:")
try:
    conn.execute(
        "SELECT " + "+".join("?" for _ in range(40000)), tuple(range(40000))
    )
    print("40000 bound params: accepted by this SQLite build")
except sqlite3.OperationalError as error:
    print("40000 bound params:", error)

cat = Catalog()
N = 40000
for i in range(N):
    cat.add_component("svc-b", "pypi", f"pkg{i}", "1.0.0")
cat.add_component("svc-a", "pypi", "shared", "1.0.0")
cat.add_component("svc-c", "pypi", "shared", "1.0.0")
cat.add_component("svc-b", "pypi", "root", "1.0.0")
# cycle: root <-> pkg0
cat.add_dependency("svc-b", "pypi", "root", "1.0.0", "svc-b", "pypi", "pkg0", "1.0.0")
cat.add_dependency("svc-b", "pypi", "pkg0", "1.0.0", "svc-b", "pypi", "root", "1.0.0")
cat.add_vulnerability("CVE-TEST-1", "shared", "high")
cat.import_osv(
    "osv-src",
    [
        {
            "id": "OSV-TEST-1",
            "affected": [
                {
                    "package": {"ecosystem": "PyPI", "name": "pkg0"},
                    "ranges": [
                        {"type": "ECOSYSTEM", "events": [{"introduced": "0"}]}
                    ],
                }
            ],
        }
    ],
)

services = cat.affected_services()
print("affected_services:", services)
summary = cat.summary()
print("summary:", summary)
print(render_summary(cat))

assert services == ["svc-a", "svc-b", "svc-c"], services
# 40000 pkgs + root + the two "shared" components (svc-a, svc-c)
assert summary.affected_components == N + 3, summary.affected_components
assert summary.components == N + 3
assert summary.vulnerabilities == 2  # manual CVE-TEST-1 + OSV-TEST-1
assert summary.highest_severity == "high"

# Empty catalog still returns an empty list.
empty = Catalog()
assert empty.affected_services() == []
print(render_summary(empty))

# Unparseable PyPI version that must be compared with an OSV record still fails.
bad = Catalog()
bad.add_component("svc-x", "pypi", "pkg0", "not-a-version!!")
bad.import_osv(
    "osv-src",
    [
        {
            "id": "OSV-TEST-2",
            "affected": [
                {
                    "package": {"ecosystem": "PyPI", "name": "pkg0"},
                    "ranges": [
                        {"type": "ECOSYSTEM", "events": [{"introduced": "0"}]}
                    ],
                }
            ],
        }
    ],
)
try:
    bad.affected_services()
except ValueError as error:
    print("unparseable version correctly raised:", error)
else:
    raise AssertionError("expected ValueError for unparseable version")

print("ALL CHECKS OK")

